import {canonicalSha256} from '../core/canonical-json.mjs';
export function buildPermissionGraph({roles=[],tools=[],flows=[]}={}){const edges=[];for(const role of roles)for(const tool of role.tools??[])edges.push({from:role.id,to:tool,type:'can-invoke'});for(const tool of tools)for(const resource of tool.resources??[])edges.push({from:tool.id,to:resource,type:'can-reach'});for(const flow of flows){edges.push({from:flow.from,to:flow.to,type:'data-flow'});if(flow.via)edges.push({from:flow.from,to:flow.via,type:'flows-via'},{from:flow.via,to:flow.to,type:'can-egress'});}const findings=[];const toolMap=new Map(tools.map(item=>[item.id,item]));for(const flow of flows){const destinationResources=toolMap.get(flow.to)?.resources??[];if(String(flow.from).startsWith('secret:')&&(String(flow.to).startsWith('network:')||destinationResources.some(item=>String(item).startsWith('network:'))))findings.push({code:'secret-exfiltration-path',severity:'critical',path:[flow.from,flow.via,flow.to,...destinationResources.filter(item=>String(item).startsWith('network:'))].filter(Boolean)});}const payload={schemaVersion:1,nodes:[...new Set(edges.flatMap(x=>[x.from,x.to]))].sort(),edges:edges.sort((a,b)=>`${a.from}>${a.to}`.localeCompare(`${b.from}>${b.to}`)),findings};return Object.freeze({...payload,graphSha256:canonicalSha256(payload)});}
export function findPermissionPaths(graph,{from,to,maxDepth=8}={}){const next=new Map();for(const edge of graph.edges){if(!next.has(edge.from))next.set(edge.from,[]);next.get(edge.from).push(edge.to);}const paths=[];const queue=[[from]];while(queue.length){const path=queue.shift();const tail=path.at(-1);if(path.length>maxDepth+1)continue;if(tail===to){paths.push(path);continue;}for(const target of (next.get(tail)??[]).sort())if(!path.includes(target))queue.push([...path,target]);}return paths;}
